  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "A high-transfer lipophilic amide/heterocycle analogue showed a 2.05-fold increase in brain penetration and was classified as BBB-permeable, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Moclobemide, a neutral amide-containing compound, achieved a human CSF/plasma ratio of 0.5 and good brain penetration, demonstrating that amide-rich molecules can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "ONO-4040552, a lipophilic amide/sulfonamide, was identified as CNS penetrant in rats with a Kp,uu of 0.15, supporting meaningful brain exposure despite moderate unbound partitioning.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A structurally related lipophilic amide/urea analogue concentrated in mouse brain (1.80 µM vs 0.12 µM plasma), providing direct evidence of high brain penetration for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "MK-4232, a larger lipophilic amide/lactam CGRP antagonist, showed good rhesus monkey brain uptake by PET, indicating that larger amide-containing scaffolds can still achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ro 19-6327 crossed the human blood-brain barrier in PET studies, confirming that amide-containing compounds with moderate polarity can have meaningful CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate CNS penetration via direct brain, CSF, or PET measurements. The consistent positive in vivo evidence outweighs the moderate physicochemical prior, so the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement exists for the exact query molecule.",
    "The magnitude of unbound brain exposure is uncertain because some positive analogues have modest Kp,uu values.",
    "Efflux-transporter status for the query is not directly measured, though high lipophilicity could increase protein binding or transporter recognition."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

